mapper.select:
/** [sql-materialInfo.xml] MaterialInfoMapper.getMaterial **/ SELECT CM08.CM08_NAME , ST02.ST02_CODE , ST01.ST01_QTY , CM05.CM05_NAME FROM TB_ST_02 ST02 INNER JOIN TB_ST_01 ST01 ON ST02.ST02_COMPANY = ST01.ST01_COMPANY AND ST02.ST02_FACTORY = ST01.ST01_FACTORY AND ST02.ST02_LOT_SEQ = ST01.ST01_LOT_SEQ LEFT JOIN TB_CM_08 CM08 ON CM08.CM08_COMPANY = ST02.ST02_COMPANY AND CM08.CM08_FACTORY = ST02.ST02_FACTORY AND CM08.CM08_CODE = ST02.ST02_CODE LEFT JOIN TB_CM_05 CM05 ON CM05.CM05_COMPANY = ST02.ST02_COMPANY AND CM05.CM05_FACTORY = ST02.ST02_FACTORY AND CM05.CM05_CODE = 'W005' AND CM05.CM05_VALUE = ST02.ST02_STATUS WHERE 1=1 AND ST02.ST02_COMPANY = #{company} AND ST02.ST02_FACTORY = #{factory}
AND ST02.ST02_QRCODE = #{qrCode}
AND ST02.ST02_LOT_SEQ = #{st02LotSeq}
AND ROWNUM = 1 ORDER BY ST02.ST02_NO DESC
